def normalize_weights(scores):
    weights = torch.softmax(scores, dim=-1)
    return torch.nan_to_num(weights, nan=0.0)

def collect(self, x):
    batch, parts, length, chunk = x.shape
    return x.transpose(1, 2).contiguous().view(batch, length, parts * chunk)

